from collections import Counter
def bg_of(grid): return Counter(v for row in grid for v in row).most_common(1)[0][0]

def complete_partial_lines(grid, fill=1):
    """A long partial line from col 0 whose complete twin spans the width elsewhere: missing bg cells become fill."""
    h, w = len(grid), len(grid[0]); bg = bg_of(grid)
    full = {r[0] for r in grid if len(set(r)) == 1}
    out = [r[:] for r in grid]
    for i, row in enumerate(grid):
        c = row[0]
        if c != bg and c in full and any(v != c for v in row):
            j = 0
            while j < w and row[j] == c: j += 1
            if j > w/2 and all(v == bg for v in row[j:]):
                out[i] = [c]*j + [fill]*(w-j)
    return out

def vperiod_fill(grid, fill=1):
    """Cells that are background but non-background at their vertical-period reference become fill."""
    h, w = len(grid), len(grid[0]); bg = bg_of(grid)
    best = None
    for p in range(1, h):
        ok = all(grid[r][j] == grid[r-p][j]
                 for r in range(p, h) for j in range(w)
                 if grid[r][j] != bg and grid[r-p][j] != bg)
        if not ok: continue
        nf = sum(1 for r in range(p, h) for j in range(w)
                 if grid[r][j] == bg and grid[r-p][j] != bg)
        if best is None or nf < best[1]:
            best = (p, nf)
    out = [r[:] for r in grid]
    if best and best[1] > 0:
        p = best[0]
        for r in range(p, h):
            for j in range(w):
                if grid[r][j] == bg and grid[r-p][j] != bg:
                    out[r][j] = fill
    return out

def transform(grid):
    return vperiod_fill(complete_partial_lines(grid))

